<?php
require_once __DIR__.'/../src/Database.php'; require_once __DIR__.'/../src/Finance.php'; require_once __DIR__.'/../src/Repository.php';
try{$db=Database::connection();$db->beginTransaction();$r=new Repository($db);$doc='TEST-'.bin2hex(random_bytes(4));$id=$r->createParticipant(['document'=>$doc,'full_name'=>'Prueba V2','phone'=>'3000000000','email'=>'test@example.com']);$found=$r->participants('Prueba V2');if(!$found)throw new RuntimeException('CRUD de participantes no encontró el registro');$r->updateParticipant($id,['document'=>$doc,'full_name'=>'Prueba Editada','phone'=>'3111111111','email'=>'edit@example.com']);if(!$r->participants('Prueba Editada'))throw new RuntimeException('edición no persistió');$r->setParticipantActive($id,false);if(count($r->participants('',true))!==count($r->participants('',null))-1)throw new RuntimeException('desactivación inválida');$r->setParticipantActive($id,true);$r->recordContribution($id,2099,1,50000);$r->resetContribution($id,2099,1);try{$r->deleteParticipant($id);throw new RuntimeException('permitió eliminar historial');}catch(RuntimeException $expected){if($expected->getMessage()!=='No se puede eliminar un participante con historial financiero.')throw $expected;}$db->rollBack();echo "PASS repository CRUD, edición, estados y protección de historial\n";}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();fwrite(STDERR,'FAIL repository: '.$e->getMessage().PHP_EOL);exit(1);}
